-- College Complaint Management System schema for Supabase PostgreSQL.
-- Execute this file before seed.sql. UUIDs are generated by PostgreSQL.

CREATE TABLE departments (
    department_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    department_name VARCHAR(120) NOT NULL UNIQUE,
    description TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE users (
    user_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    department_id UUID,
    full_name VARCHAR(160) NOT NULL,
    email VARCHAR(320) NOT NULL UNIQUE,
    password_hash VARCHAR(255) NOT NULL,
    role VARCHAR(20) NOT NULL,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_users_department
        FOREIGN KEY (department_id) REFERENCES departments (department_id) ON DELETE RESTRICT,
    CONSTRAINT ck_users_role CHECK (role IN ('STUDENT', 'FACULTY', 'ADMIN')),
    CONSTRAINT ck_faculty_department CHECK (role <> 'FACULTY' OR department_id IS NOT NULL)
);

CREATE TABLE buildings (
    building_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    building_name VARCHAR(120) NOT NULL UNIQUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE floors (
    floor_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    building_id UUID NOT NULL,
    floor_number INTEGER NOT NULL,
    floor_name VARCHAR(80) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_floors_building
        FOREIGN KEY (building_id) REFERENCES buildings (building_id) ON DELETE RESTRICT,
    CONSTRAINT ck_floors_number CHECK (floor_number >= 0),
    CONSTRAINT uq_floors_building_number UNIQUE (building_id, floor_number),
    -- Required as the target of complaints' composite building/floor foreign key.
    CONSTRAINT uq_floors_building_floor UNIQUE (building_id, floor_id)
);

-- A selectable place can be a classroom, lab, canteen, court, gym, field, or common area.
CREATE TABLE classrooms (
    classroom_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    floor_id UUID NOT NULL,
    classroom_number VARCHAR(40) NOT NULL,
    classroom_name VARCHAR(120) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_classrooms_floor
        FOREIGN KEY (floor_id) REFERENCES floors (floor_id) ON DELETE RESTRICT,
    CONSTRAINT uq_classrooms_floor_number UNIQUE (floor_id, classroom_number),
    -- Required as the target of complaints' composite floor/classroom foreign key.
    CONSTRAINT uq_classrooms_floor_classroom UNIQUE (floor_id, classroom_id)
);

CREATE TABLE complaint_categories (
    category_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    department_id UUID,
    category_name VARCHAR(120) NOT NULL UNIQUE,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_categories_department
        FOREIGN KEY (department_id) REFERENCES departments (department_id) ON DELETE RESTRICT
);

CREATE TABLE complaints (
    complaint_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    complaint_title VARCHAR(200) NOT NULL,
    description TEXT NOT NULL,
    category_id UUID NOT NULL,
    department_id UUID,
    building_id UUID NOT NULL,
    floor_id UUID NOT NULL,
    classroom_id UUID NOT NULL,
    status VARCHAR(20) NOT NULL DEFAULT 'PENDING',
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    removed_at TIMESTAMPTZ,
    removed_by_user_id UUID,
    removal_reason TEXT,
    CONSTRAINT fk_complaints_category
        FOREIGN KEY (category_id) REFERENCES complaint_categories (category_id) ON DELETE RESTRICT,
    CONSTRAINT fk_complaints_department
        FOREIGN KEY (department_id) REFERENCES departments (department_id) ON DELETE RESTRICT,
    CONSTRAINT fk_complaints_removed_by
        FOREIGN KEY (removed_by_user_id) REFERENCES users (user_id) ON DELETE RESTRICT,
    -- These composite keys make it impossible to pair a classroom with a different floor/building.
    CONSTRAINT fk_complaints_building_floor
        FOREIGN KEY (building_id, floor_id) REFERENCES floors (building_id, floor_id) ON DELETE RESTRICT,
    CONSTRAINT fk_complaints_floor_classroom
        FOREIGN KEY (floor_id, classroom_id) REFERENCES classrooms (floor_id, classroom_id) ON DELETE RESTRICT,
    CONSTRAINT ck_complaints_status
        CHECK (status IN ('PENDING', 'ASSIGNED', 'IN_PROGRESS', 'RESOLVED', 'REJECTED')),
    CONSTRAINT ck_complaints_removal_metadata CHECK (
        (removed_at IS NULL AND removed_by_user_id IS NULL AND removal_reason IS NULL)
        OR (removed_at IS NOT NULL AND removed_by_user_id IS NOT NULL AND removal_reason IS NOT NULL)
    )
);

CREATE TABLE complaint_images (
    image_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    complaint_id UUID NOT NULL,
    storage_path VARCHAR(500) NOT NULL UNIQUE,
    content_type VARCHAR(50) NOT NULL,
    file_size_bytes BIGINT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_images_complaint
        FOREIGN KEY (complaint_id) REFERENCES complaints (complaint_id) ON DELETE RESTRICT,
    CONSTRAINT ck_images_content_type
        CHECK (content_type IN ('image/jpeg', 'image/png')),
    CONSTRAINT ck_images_file_size CHECK (file_size_bytes > 0 AND file_size_bytes <= 5242880)
);

CREATE TABLE complaint_status_history (
    history_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    complaint_id UUID NOT NULL,
    previous_status VARCHAR(20),
    new_status VARCHAR(20) NOT NULL,
    remarks TEXT,
    changed_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_status_history_complaint
        FOREIGN KEY (complaint_id) REFERENCES complaints (complaint_id) ON DELETE RESTRICT,
    CONSTRAINT ck_history_previous_status
        CHECK (previous_status IS NULL OR previous_status IN ('PENDING', 'ASSIGNED', 'IN_PROGRESS', 'RESOLVED', 'REJECTED')),
    CONSTRAINT ck_history_new_status
        CHECK (new_status IN ('PENDING', 'ASSIGNED', 'IN_PROGRESS', 'RESOLVED', 'REJECTED'))
);

-- Private join between a complaint and its authenticated submitter.
-- Do not add user_id or other submitter data to complaints or handler-facing views.
CREATE TABLE complaint_ownership (
    ownership_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    complaint_id UUID NOT NULL UNIQUE,
    user_id UUID NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_ownership_complaint
        FOREIGN KEY (complaint_id) REFERENCES complaints (complaint_id) ON DELETE RESTRICT,
    CONSTRAINT fk_ownership_user
        FOREIGN KEY (user_id) REFERENCES users (user_id) ON DELETE RESTRICT
);

-- Supabase clients using the anon/authenticated roles cannot read ownership records.
-- There are intentionally no client-facing RLS policies on this table. The backend must
-- use its private database connection and authorize access in application services.
ALTER TABLE complaint_ownership ENABLE ROW LEVEL SECURITY;

-- All application access goes through the authenticated backend API. These tables
-- intentionally have no anon/authenticated Data API policies. The backend uses the
-- private database role and performs owner/handler checks before returning records.
ALTER TABLE departments ENABLE ROW LEVEL SECURITY;
ALTER TABLE users ENABLE ROW LEVEL SECURITY;
ALTER TABLE buildings ENABLE ROW LEVEL SECURITY;
ALTER TABLE floors ENABLE ROW LEVEL SECURITY;
ALTER TABLE classrooms ENABLE ROW LEVEL SECURITY;
ALTER TABLE complaint_categories ENABLE ROW LEVEL SECURITY;
ALTER TABLE complaints ENABLE ROW LEVEL SECURITY;
ALTER TABLE complaint_images ENABLE ROW LEVEL SECURITY;
ALTER TABLE complaint_status_history ENABLE ROW LEVEL SECURITY;

CREATE INDEX idx_users_department_id ON users (department_id);
CREATE INDEX idx_users_role_active ON users (role, is_active);
CREATE INDEX idx_categories_department_id ON complaint_categories (department_id);
CREATE INDEX idx_complaints_status_created_at ON complaints (status, created_at DESC);
CREATE INDEX idx_complaints_department_status ON complaints (department_id, status);
CREATE INDEX idx_complaints_location ON complaints (building_id, floor_id, classroom_id);
CREATE INDEX idx_complaints_floor_classroom ON complaints (floor_id, classroom_id);
CREATE INDEX idx_complaints_category_id ON complaints (category_id);
CREATE INDEX idx_complaints_active_department_created_at
    ON complaints (department_id, created_at DESC) WHERE removed_at IS NULL;
CREATE INDEX idx_complaint_images_complaint_id ON complaint_images (complaint_id);
CREATE INDEX idx_status_history_complaint_changed_at ON complaint_status_history (complaint_id, changed_at DESC);
CREATE INDEX idx_complaint_ownership_user_id_created_at ON complaint_ownership (user_id, created_at DESC);
